import { describe, it, expect } from 'vitest';
import { quoteTotal, unitPriceFor } from '../app/pricing/rate-card';

describe('rate card quoting', () => {
  it('quotes the base tier for small orders', () => {
    expect(quoteTotal(3)).toEqual(2550);
  });

  it('prices the volume boundary at exactly fifty units', () => {
    expect(unitPriceFor(50)).toEqual(345);
    expect(quoteTotal(50)).toEqual(18450);
  });

  it('prices a single unit at the published rate', () => {
    expect(unitPriceFor(1)).toEqual(450);
  });

  it('prices bulk orders on the volume tier', () => {
    expect(quoteTotal(120)).toEqual(42600);
  });

  it('keeps the quoting surface callable from the checkout flow', () => {
    expect(quoteTotal(12)).toEqual(6000);
  });
});

